import sys

def count_equivalence_classes(S):
    n = len(S)
    seen = set()

    for i in range(n):
        count_ones = 0
        for j in range(i, n):
            count_ones += 1 if S[j] == '1' else 0
            if count_ones % 2 == 0:
                seen.add(S[i:j+1])

    return len(seen)

def main():
    import sys
    input = sys.stdin.read().splitlines()
    T = int(input[0])
    results = []
    index = 1
    for _ in range(T):
        S = input[index]
        result = count_equivalence_classes(S)
        results.append(result)
        index += 1
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
